const template03Meta_hbs = "<title>Standard Article Template</title>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Dela+Gothic+One&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');\n\n  :root{\n    --blue:#2D2DFF;\n    --blue-hover:#0000CC;\n    --black:#0A0A0A;\n    --surface:#111111;\n    --grey:#8C8C8C;\n    --white:#FFFFFF;\n    --border:#FFFFFF;\n    --hairline:rgba(255,255,255,0.14);\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;}\n  body{\n    background:var(--black);\n    color:var(--white);\n    font-family:'Space Grotesk',sans-serif;\n    line-height:1.65;\n    -webkit-font-smoothing:antialiased;\n  }\n  ::selection{background:var(--blue);color:var(--white);}\n  h1,h2,h3{margin:0;text-wrap:balance;}\n  p{margin:0;}\n  a{color:inherit;text-decoration:none;}\n  img,svg{display:block;max-width:100%;}\n  .wrap{max-width:1180px;margin:0 auto;padding-inline:24px;}\n  @media(min-width:900px){.wrap{padding-inline:80px;}}\n  @media(min-width:1440px){.wrap{padding-inline:96px;}}\n\n  .grid-tex{\n    position:absolute;inset:0;\n    background-image:\n      linear-gradient(to right, rgba(255,255,255,0.05) 1px, transparent 1px),\n      linear-gradient(to bottom, rgba(255,255,255,0.05) 1px, transparent 1px);\n    background-size:32px 32px;\n    pointer-events:none;\n  }\n\n  /* Header/footer are intentionally not part of this output — the article\n     is meant to be embedded into the real EDT site/CMS, which supplies its\n     own. .btn/.btn-primary/.btn-ghost/.arrow are kept: the dynamic CTA\n     section at the bottom still uses them. */\n  .btn{\n    display:inline-flex;align-items:center;gap:9px;\n    font-family:'Space Grotesk',sans-serif;font-weight:600;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;\n    padding:13px 22px;border:1px solid var(--blue);\n    transition:background 120ms ease,color 120ms ease,transform 120ms ease;\n  }\n  .btn-primary{background:var(--blue);color:var(--white);}\n  .btn-primary:hover{background:var(--blue-hover);transform:scale(1.02);}\n  .btn-ghost{background:transparent;border-color:var(--white);}\n  .btn-ghost:hover{background:var(--white);color:var(--black);}\n  .arrow{transition:transform 120ms ease;display:inline-block;}\n  .btn:hover .arrow{transform:translateX(3px);}\n\n  /* ================= CRUMB ================= */\n  .crumb-bar{border-bottom:1px solid var(--hairline);}\n  .crumb-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:var(--grey);}\n  .crumb-row .sep{color:var(--blue);margin:0 8px;}\n\n  /* ================= ARTICLE HERO ================= */\n  .article-hero{position:relative;overflow:hidden;padding:56px 0 40px;}\n  .eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:600;letter-spacing:0.14em;text-transform:uppercase;color:var(--blue);margin-bottom:20px;}\n  .eyebrow::before{content:\"\";width:8px;height:8px;background:var(--blue);}\n  h1.title{\n    font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;letter-spacing:-0.02em;\n    font-size:clamp(32px,6vw,60px);line-height:1.05;max-width:22ch;\n  }\n  .dek{margin-top:22px;max-width:62ch;font-size:clamp(16px,1.8vw,19px);color:#cfcfcf;font-weight:300;}\n  .byline-row{margin-top:32px;display:flex;flex-wrap:wrap;border-top:1px solid var(--hairline);}\n  .byline-item{flex:1 1 130px;padding:14px 20px;border-right:1px solid var(--hairline);}\n  .byline-item:first-child{padding-left:0;}\n  .byline-item:last-child{border-right:none;}\n  .byline-item .k{font-size:10px;letter-spacing:0.1em;text-transform:uppercase;color:var(--grey);margin-bottom:5px;}\n  .byline-item .v{font-size:13px;font-weight:500;}\n\n  /* ================= LAYOUT: BODY + TOC ================= */\n  .article-layout{padding:8px 0 32px;}\n  .layout-grid{display:grid;grid-template-columns:1fr;gap:48px;}\n  @media(min-width:980px){\n    .layout-grid{grid-template-columns:190px 1fr;gap:56px;align-items:start;}\n  }\n\n  /* ---- TOC ---- */\n  .toc-wrap{border:1px solid var(--hairline);background:var(--surface);order:-1;}\n  @media(min-width:980px){\n    .toc-wrap{position:sticky;top:24px;order:0;}\n  }\n  .toc-head{\n    display:flex;align-items:center;justify-content:space-between;\n    padding:12px 16px;border-bottom:1px solid var(--hairline);\n  }\n  .toc-head span{font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:var(--grey);}\n  .toc-list{list-style:none;margin:0;padding:8px 0;}\n  .toc-list li{margin:0;}\n  .toc-list a{\n    display:flex;gap:8px;align-items:baseline;\n    padding:9px 14px;font-size:12.5px;line-height:1.4;color:var(--grey);\n    border-left:2px solid transparent;transition:color .2s ease, border-color .2s ease;\n  }\n  .toc-list a .n{font-size:10px;color:var(--grey);flex-shrink:0;}\n  .toc-list a:hover{color:var(--white);}\n  .toc-list a.active{color:var(--white);border-left-color:var(--blue);background:rgba(45,45,255,0.08);}\n  .toc-list a.active .n{color:var(--blue);}\n  .toc-progress{height:2px;background:var(--hairline);}\n  .toc-progress-bar{height:100%;width:0%;background:var(--blue);transition:width 120ms linear;}\n\n  /* ---- Article body ---- */\n  .article-main{min-width:0;}\n  .lede{font-size:18px;font-weight:400;color:#e8e8e8;margin-bottom:40px;line-height:1.7;max-width:70ch;}\n  .article-section{padding:40px 0;border-top:1px solid var(--hairline);scroll-margin-top:24px;}\n  .article-section:first-child{border-top:none;padding-top:0;}\n  .article-section h2{\n    font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:clamp(22px,2.6vw,28px);margin-bottom:18px;\n  }\n  .article-section p{font-size:16px;color:#d6d6d6;font-weight:300;line-height:1.8;margin-bottom:20px;max-width:70ch;}\n  .article-section p:last-child{margin-bottom:0;}\n  .article-section ul{margin:0 0 20px;padding-left:0;list-style:none;max-width:70ch;}\n  .article-section ul li{\n    position:relative;padding-left:22px;margin-bottom:12px;font-size:16px;color:#d6d6d6;font-weight:300;line-height:1.7;\n  }\n  .article-section ul li::before{content:\"→\";position:absolute;left:0;color:var(--blue);font-weight:700;}\n\n  /* ---- comparison table ---- */\n  .table-scroll{overflow-x:auto;margin:8px 0 28px;border:1px solid var(--hairline);}\n  table{width:100%;border-collapse:collapse;min-width:520px;font-size:14px;}\n  th,td{padding:14px 16px;text-align:left;border-bottom:1px solid var(--hairline);}\n  thead th{\n    background:var(--surface);font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:var(--blue);\n    font-weight:700;border-bottom:1px solid var(--border);\n  }\n  tbody td{color:#d6d6d6;font-weight:300;}\n  tbody td:first-child{color:var(--white);font-weight:500;}\n  tbody tr:last-child td{border-bottom:none;}\n\n  .callout{\n    margin:32px 0;padding:20px 24px;border:1px solid var(--blue);background:rgba(45,45,255,0.06);max-width:70ch;\n  }\n  .callout .label{font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:var(--blue);margin-bottom:8px;display:block;}\n  .callout p{margin-bottom:0;color:#e8e8e8;}\n\n  .closing{padding-top:8px;}\n  .closing p{font-size:16px;color:#d6d6d6;font-weight:300;line-height:1.8;max-width:70ch;}\n\n  /* ================= CTA ================= */\n  .cta{padding:88px 0;border-top:1px solid var(--hairline);margin-top:32px;}\n  .cta h2{font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;font-size:clamp(28px,5vw,48px);letter-spacing:-0.02em;max-width:16ch;margin-bottom:18px;}\n  .cta p{color:var(--grey);font-size:16px;max-width:52ch;margin-bottom:32px;font-weight:300;}\n  .cta-btns{display:flex;flex-wrap:wrap;gap:16px;}\n</style>\n\n<div class=\"crumb-bar\">\n  <div class=\"wrap crumb-row\">\n    <div><a href=\"#\">Blog</a><span class=\"sep\">/</span><a href=\"#\">{{category}}</a></div>\n  </div>\n</div>\n\n<section class=\"article-hero\">\n  <div class=\"grid-tex\" style=\"opacity:.5\"></div>\n  <div class=\"wrap\" style=\"position:relative;\">\n    <div class=\"eyebrow\">{{eyebrowText}}</div>\n    <h1 class=\"title\">{{title}}</h1>\n    <p class=\"dek\">{{dek}}</p>\n    <div class=\"byline-row\">\n      <div class=\"byline-item\"><div class=\"k\">Author</div><div class=\"v\">{{authorLabel}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Category</div><div class=\"v\">{{category}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Read time</div><div class=\"v\">{{readTimeLabel}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Published</div><div class=\"v\">{{publishedLabel}}</div></div>\n    </div>\n  </div>\n</section>\n\n<section class=\"article-layout\">\n  <div class=\"wrap layout-grid\">\n\n    <aside class=\"toc-wrap\">\n      <div class=\"toc-head\"><span>On this page</span></div>\n      <div class=\"toc-progress\"><div class=\"toc-progress-bar\" id=\"tocProgress\"></div></div>\n      <ul class=\"toc-list\" id=\"tocList\">\n        {{#each tocSections}}\n        <li><a href=\"#{{this.anchor}}\"><span class=\"n\">{{pad2 @index}}</span>{{this.heading}}</a></li>\n        {{/each}}\n      </ul>\n    </aside>\n\n    <div class=\"article-main\">\n      <p class=\"lede\">{{lede}}</p>\n\n      {{#each bodyItems}}\n      {{#if this.videoHtml}}\n      {{{this.videoHtml}}}\n      {{else if (eq this.type \"section\")}}\n      <div class=\"article-section\" id=\"{{this.anchor}}\">\n        <h2>{{this.heading}}</h2>\n        {{#each this.blocks}}\n        {{{renderBlock this}}}\n        {{/each}}\n      </div>\n      {{else}}\n      {{{renderCallout this}}}\n      {{/if}}\n      {{/each}}\n\n      {{#if (eq galleryPlacement \"mid-article\")}}\n      {{{galleryHtml}}}\n      {{/if}}\n\n    </div>\n  </div>\n</section>\n\n{{#if (eq galleryPlacement \"before-cta\")}}\n{{{galleryHtml}}}\n{{/if}}\n\n{{#if cta}}\n<section class=\"cta\">\n  <div class=\"wrap\">\n    <h2>{{cta.heading}}</h2>\n    <p>{{cta.body}}</p>\n    <div class=\"cta-btns\">\n      <a class=\"btn btn-primary\" href=\"#\">Get a quote<span class=\"arrow\">→</span></a>\n      <a class=\"btn btn-ghost\" href=\"#\">See our work<span class=\"arrow\">→</span></a>\n    </div>\n  </div>\n</section>\n{{/if}}\n\n<script>\n  var links = Array.prototype.slice.call(document.querySelectorAll('#tocList a'));\n  var sections = links.map(function(a){ return document.querySelector(a.getAttribute('href')); });\n  var progressBar = document.getElementById('tocProgress');\n\n  function setActive(id){\n    links.forEach(function(a){\n      a.classList.toggle('active', a.getAttribute('href') === '#' + id);\n    });\n  }\n\n  // Scroll via scrollIntoView rather than relying on the browser's native\n  // same-page anchor navigation: when this article is shown inside a\n  // sandboxed preview iframe with only allow-scripts (no allow-same-origin\n  // — deliberately, so the frame can't reach into the host page), native\n  // fragment navigation is unreliable — it can silently no-op, or in some\n  // configurations blank the frame entirely. A direct DOM scroll sidesteps\n  // that altogether and works the same standalone or embedded.\n  links.forEach(function(a){\n    a.addEventListener('click', function(event){\n      var target = document.querySelector(a.getAttribute('href'));\n      if (!target) return;\n      event.preventDefault();\n      target.scrollIntoView({ behavior: 'smooth', block: 'start' });\n      setActive(target.id);\n    });\n  });\n\n  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {\n    var io = new IntersectionObserver(function(entries){\n      entries.forEach(function(entry){\n        if (entry.isIntersecting) setActive(entry.target.id);\n      });\n    }, { rootMargin: '-15% 0px -70% 0px' });\n    sections.forEach(function(s){ if (s) io.observe(s); });\n  }\n\n  function updateProgress(){\n    var h = document.documentElement;\n    var max = h.scrollHeight - h.clientHeight;\n    progressBar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';\n  }\n  document.addEventListener('scroll', updateProgress, { passive: true });\n  updateProgress();\n</script>\n";
const template03Meta_exampleJson = "{\n  \"title\": \"AR, VR OR MIXED REALITY: WHICH ONE ACTUALLY FITS YOUR EVENT?\",\n  \"dek\": \"A practical guide to picking the right immersive format before you brief a vendor — what each one is good at, what it costs, and the questions that save you a rebuild.\",\n  \"category\": \"Insights\",\n  \"readTimeMinutes\": 8,\n  \"lede\": \"Most format decisions get made backwards — a client picks \\\"VR\\\" or \\\"AR\\\" because it's the word that came up in the meeting, then briefs a vendor to make it work. Flip that order and the decision gets much easier: start from what the audience needs to walk away with, and the format usually picks itself.\",\n  \"bodyItems\": [\n    {\n      \"type\": \"section\",\n      \"heading\": \"Start with the outcome, not the tech\",\n      \"navLabel\": \"Start with the outcome\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Before naming a format, answer one question: does this need to happen on a real, physical thing the audience is standing in front of, or does it need to happen somewhere that doesn't exist yet? That single split does most of the filtering. A product reveal happening on a real stage in front of a real crowd is a different brief than a training scenario that needs a space no one can safely build in real life.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Everything below assumes you've answered that question first. If you haven't, the comparison table further down won't help much — it'll just make three options sound equally plausible.\"\n        }\n      ]\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"What AR is actually good for\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Augmented reality earns its keep when the real environment is doing half the work. It's layering — information, characters, or effects placed on top of something that's already there: a product on a shelf, a building on a heritage trail, a mascot on an event floor. AR works best when you want the audience to keep their attention split between the real world and the layer you've added, not fully replace one with the other.\"\n        },\n        {\n          \"kind\": \"bulletList\",\n          \"items\": [\n            \"Product try-on and visualisation, where seeing it on yourself or your own space is the point\",\n            \"Heritage and wayfinding trails, where the physical location carries meaning AR can't replace\",\n            \"Event activations with high foot traffic, since AR needs no headset queue to run\"\n          ]\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"What VR is actually good for\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Virtual reality earns its keep when the real environment is the problem, not the asset. Training scenarios that are too dangerous, too expensive, or physically impossible to stage for real — an earthquake, a forklift accident, a factory floor that doesn't exist yet — are where VR stops being a novelty and starts being the only practical way to rehearse something.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"It's also the strongest option when you want full control over pacing and attention: no ambient noise, no distractions, one person fully inside one experience at a time. That control is a feature for training and a limitation for large-crowd events, where a headset queue caps how many people you can move through in a day.\"\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"What mixed reality adds\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Mixed reality sits between the two — digital objects that don't just sit on top of the real world but respond to it, aware of the room's geometry and the people in it. It's the right call when the brief genuinely needs both halves at once: a real presenter interacting with a virtual object the whole room can see respond to touch, or a hybrid broadcast where a virtual set has to react to a live physical performer.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"It's also the format most likely to be over-specified. If the brief doesn't actually need real and virtual elements to interact, mixed reality adds cost and complexity that AR or VR alone would have solved more simply.\"\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"callout\",\n      \"label\": \"EDT's rule of thumb\",\n      \"body\": \"If you can describe the experience without using the word \\\"immersive,\\\" you probably know which format you need already. If the word \\\"immersive\\\" is doing all the work in your brief, that's usually a sign the outcome hasn't been defined yet — and no format fixes that on its own.\"\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"Side-by-side comparison\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"A rough guide — real numbers depend on scope, but this is the shape of the trade-off we walk clients through first.\"\n        },\n        {\n          \"kind\": \"comparisonTable\",\n          \"columns\": [\n            \"Format\",\n            \"Best for\",\n            \"Hardware\",\n            \"Crowd throughput\"\n          ],\n          \"rows\": [\n            [\n              \"AR\",\n              \"Layering onto a real product, place, or person\",\n              \"Phone or tablet\",\n              \"High — no queue needed\"\n            ],\n            [\n              \"VR\",\n              \"Scenarios too costly or dangerous to stage for real\",\n              \"Headset, per person\",\n              \"Low — one person at a time\"\n            ],\n            [\n              \"Mixed reality\",\n              \"Real and virtual elements that must react to each other\",\n              \"Headset or tracked camera\",\n              \"Moderate — depends on setup\"\n            ]\n          ]\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"Budget and timeline reality\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"AR is almost always the fastest and cheapest of the three to deploy at scale, since it runs on a device most of your audience already has in their pocket. VR carries hardware cost on top of build cost — every headset is a line item, and a large activation means either owning a fleet of them or renting one. Mixed reality tends to sit at the top of both budget and timeline, because it's solving two problems (a real environment and a virtual one) that have to be built to work together, not separately.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"None of that means \\\"pick the cheap one.\\\" It means the format should already be decided by the outcome before cost enters the conversation — otherwise budget ends up choosing the format for you, and the outcome quietly gets smaller to fit it.\"\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"Questions to ask your vendor\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"A short list that tends to surface whether a vendor has actually thought through your brief, or is fitting your brief to whatever they already built last time:\"\n        },\n        {\n          \"kind\": \"bulletList\",\n          \"items\": [\n            \"What happens to this experience for the person who's third in line, not first?\",\n            \"What's the plan if the venue's wifi or lighting isn't what was promised?\",\n            \"Who owns the build after the event — can it be reused, or does it die with the activation?\",\n            \"What's the fallback if a headset or device fails mid-event?\"\n          ]\n        },\n        {\n          \"kind\": \"closingNote\",\n          \"body\": \"None of these questions are about the technology. They're about whether the studio has run something like this before, in a room like yours, for an audience like the one you're actually inviting. That's usually a better filter than the format name on the brief.\"\n        }\n      ],\n      \"navLabel\": null\n    }\n  ],\n  \"cta\": {\n    \"heading\": \"Still not sure which format fits?\",\n    \"body\": \"Tell us the outcome you're actually after and we'll tell you straight whether that's an AR, VR, or mixed reality brief — before you commit to a build.\"\n  },\n  \"galleryPlacement\": null\n}\n";

const template01Meta_hbs = "<title>Case Study Roundup Template</title>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Dela+Gothic+One&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');\n\n  :root{\n    --blue:#2D2DFF;\n    --blue-hover:#0000CC;\n    --black:#0A0A0A;\n    --surface:#111111;\n    --grey:#8C8C8C;\n    --white:#FFFFFF;\n    --border:#FFFFFF;\n    --hairline:rgba(255,255,255,0.14);\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;}\n  body{\n    background:var(--black);\n    color:var(--white);\n    font-family:'Space Grotesk',sans-serif;\n    line-height:1.65;\n    -webkit-font-smoothing:antialiased;\n  }\n  ::selection{background:var(--blue);color:var(--white);}\n  h1,h2,h3{margin:0;text-wrap:balance;}\n  p{margin:0;}\n  a{color:inherit;text-decoration:none;}\n  img,svg{display:block;max-width:100%;}\n  .wrap{max-width:1180px;margin:0 auto;padding-inline:24px;}\n  @media(min-width:900px){.wrap{padding-inline:80px;}}\n\n  .grid-tex{\n    position:absolute;inset:0;\n    background-image:\n      linear-gradient(to right, rgba(255,255,255,0.05) 1px, transparent 1px),\n      linear-gradient(to bottom, rgba(255,255,255,0.05) 1px, transparent 1px);\n    background-size:32px 32px;\n    pointer-events:none;\n  }\n\n  /* Header/footer/template-tag are intentionally not part of this output —\n     the article is meant to be embedded into the real EDT site/CMS, which\n     supplies its own. .btn/.btn-primary/.btn-ghost/.arrow are kept: the\n     dynamic CTA section at the bottom still uses them. */\n  .btn{\n    display:inline-flex;align-items:center;gap:9px;\n    font-family:'Space Grotesk',sans-serif;font-weight:600;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;\n    padding:13px 22px;border:1px solid var(--blue);\n    transition:background 120ms ease,color 120ms ease,transform 120ms ease;\n  }\n  .btn-primary{background:var(--blue);color:var(--white);}\n  .btn-primary:hover{background:var(--blue-hover);transform:scale(1.02);}\n  .btn-ghost{background:transparent;border-color:var(--white);}\n  .btn-ghost:hover{background:var(--white);color:var(--black);}\n  .arrow{transition:transform 120ms ease;display:inline-block;}\n  .btn:hover .arrow{transform:translateX(3px);}\n\n  /* ================= BREADCRUMB ================= */\n  .crumb-bar{border-bottom:1px solid var(--hairline);}\n  .crumb-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:var(--grey);}\n  .crumb-row a:hover{color:var(--blue);}\n  .crumb-row .sep{color:var(--blue);margin:0 8px;}\n\n  /* ================= ARTICLE HERO ================= */\n  .article-hero{position:relative;overflow:hidden;padding:56px 0 40px;}\n  .eyebrow{\n    display:inline-flex;align-items:center;gap:8px;\n    font-size:12px;font-weight:600;letter-spacing:0.14em;text-transform:uppercase;color:var(--blue);margin-bottom:20px;\n  }\n  .eyebrow::before{content:\"\";width:8px;height:8px;background:var(--blue);}\n  h1.title{\n    font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;letter-spacing:-0.02em;\n    font-size:clamp(34px,6vw,68px);line-height:1.02;max-width:18ch;\n  }\n  .dek{margin-top:24px;max-width:60ch;font-size:clamp(16px,1.8vw,18px);color:#cfcfcf;font-weight:300;}\n  .article-meta{\n    margin-top:36px;display:flex;flex-wrap:wrap;border-top:1px solid var(--hairline);\n  }\n  .meta-item{flex:1 1 150px;padding:16px 20px;border-right:1px solid var(--hairline);}\n  .meta-item:first-child{padding-left:0;}\n  .meta-item:last-child{border-right:none;}\n  .meta-item .k{font-size:10px;letter-spacing:0.1em;text-transform:uppercase;color:var(--grey);margin-bottom:5px;}\n  .meta-item .v{font-size:13px;font-weight:500;}\n\n  .intro{padding:0 0 56px;border-bottom:1px solid var(--hairline);}\n  .intro p{max-width:70ch;font-size:17px;color:#dcdcdc;font-weight:300;margin-bottom:18px;}\n  .intro p:last-child{margin-bottom:0;}\n  .intro a{color:var(--blue);text-decoration:underline;text-underline-offset:3px;}\n\n  /* ================= ROUNDUP LIST ================= */\n  .roundup{padding:8px 0 40px;}\n  .entry{\n    display:grid;grid-template-columns:1fr;gap:32px;\n    padding:64px 0;border-bottom:1px solid var(--hairline);\n  }\n  @media(min-width:860px){\n    .entry{grid-template-columns:1fr 1fr;gap:64px;align-items:center;}\n    .entry.flip .media{order:2;}\n    .entry.flip .copy{order:1;}\n    /* No photo for this entry: the media column is omitted entirely\n       (guarded further down, per-entry) rather than left as an empty\n       frame, so the copy column takes the full row instead of leaving\n       a blank second column. */\n    .entry.no-media{grid-template-columns:1fr;}\n    .entry.no-media .copy{max-width:70ch;}\n  }\n  .index{\n    font-family:'Dela Gothic One',sans-serif;font-size:13px;color:var(--blue);\n    letter-spacing:0.06em;margin-bottom:20px;display:block;\n  }\n  .copy h2{\n    font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:clamp(22px,2.6vw,30px);margin-bottom:18px;\n  }\n  .tag-row{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px;}\n  .tag{border:1px solid var(--border);font-size:10px;letter-spacing:0.08em;text-transform:uppercase;padding:4px 9px;color:var(--grey);}\n  .tag.blue{border-color:var(--blue);color:var(--blue);}\n  .copy p.blurb{font-size:15px;color:#c9c9c9;font-weight:300;max-width:58ch;margin-bottom:22px;}\n  .stat-line{\n    display:flex;align-items:baseline;gap:8px;font-family:'Space Grotesk',sans-serif;\n    font-size:13px;color:var(--white);font-weight:600;\n  }\n  .stat-line::before{content:\"→\";color:var(--blue);font-weight:700;}\n\n  /* ---- media / autoplay-on-scroll slot ---- */\n  .media{position:relative;}\n  .os-window{border:1px solid var(--border);background:var(--surface);}\n  .os-titlebar{\n    display:flex;align-items:center;justify-content:space-between;background:var(--blue);\n    padding:11px 16px;border-bottom:1px solid var(--border);\n  }\n  .os-titlebar .name{font-size:11px;font-weight:600;letter-spacing:0.05em;}\n  .os-btns{display:flex;gap:5px;}\n  .os-btns i{width:10px;height:10px;border:1px solid var(--white);display:block;}\n  .stage{\n    position:relative;aspect-ratio:4/3;overflow:hidden;\n    background:radial-gradient(circle at 25% 20%, rgba(45,45,255,0.28), transparent 55%), #0d0d0d;\n  }\n  .stage .thumb{\n    position:absolute;inset:0;width:100%;height:100%;object-fit:cover;\n    filter:grayscale(.3) contrast(1.15) brightness(.82) saturate(.9);\n    transform:scale(1);transition:transform 6s cubic-bezier(.19,1,.22,1);\n  }\n  .entry.is-playing .stage .thumb{transform:scale(1.08);}\n  .stage .tint{position:absolute;inset:0;background:var(--blue);opacity:.24;mix-blend-mode:multiply;}\n  .stage .vignette{position:absolute;inset:0;background:linear-gradient(180deg, rgba(0,0,0,0) 45%, rgba(0,0,0,.8) 100%);}\n  .stage .scan{\n    position:absolute;inset:0;\n    background-image:\n      linear-gradient(to right, rgba(255,255,255,0.05) 1px, transparent 1px),\n      linear-gradient(to bottom, rgba(255,255,255,0.05) 1px, transparent 1px);\n    background-size:24px 24px;\n  }\n  .glyph{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:96px;height:96px;opacity:.9;}\n  @media (prefers-reduced-motion: reduce){.stage .thumb{transition:none;}}\n\n  /* ================= CTA ================= */\n  .cta{padding:88px 0;border-top:1px solid var(--hairline);}\n  .cta h2{font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;font-size:clamp(28px,5vw,48px);letter-spacing:-0.02em;max-width:16ch;margin-bottom:18px;}\n  .cta p{color:var(--grey);font-size:16px;max-width:52ch;margin-bottom:32px;font-weight:300;}\n  .cta-btns{display:flex;flex-wrap:wrap;gap:16px;}\n</style>\n\n<div class=\"crumb-bar\">\n  <div class=\"wrap crumb-row\">\n    <div><a href=\"#\">Blog</a><span class=\"sep\">/</span><a href=\"#\">{{category}}</a></div>\n  </div>\n</div>\n\n<section class=\"article-hero\">\n  <div class=\"grid-tex\" style=\"opacity:.5\"></div>\n  <div class=\"wrap\" style=\"position:relative;\">\n    <div class=\"eyebrow\">EDT Blog — Case study roundup</div>\n    <h1 class=\"title\">{{title}}</h1>\n    <p class=\"dek\">{{dek}}</p>\n    <div class=\"article-meta\">\n      <div class=\"meta-item\"><div class=\"k\">Category</div><div class=\"v\">{{category}}</div></div>\n      <div class=\"meta-item\"><div class=\"k\">Read time</div><div class=\"v\">{{readTimeLabel}}</div></div>\n      <div class=\"meta-item\"><div class=\"k\">Format</div><div class=\"v\">{{formatLabel}}</div></div>\n      <div class=\"meta-item\"><div class=\"k\">Published</div><div class=\"v\">EDT Blog</div></div>\n    </div>\n  </div>\n</section>\n\n{{#if intro}}\n<section class=\"intro\">\n  <div class=\"wrap\">\n    <p>{{intro}}</p>\n  </div>\n</section>\n{{/if}}\n\n{{#if (eq galleryPlacement \"after-intro\")}}\n{{{galleryHtml}}}\n{{/if}}\n\n<section class=\"roundup\" id=\"roundup-list\">\n  <div class=\"wrap\">\n\n  {{#each entries}}\n  {{#if this.videoHtml}}\n  {{{this.videoHtml}}}\n  {{else}}\n  <article class=\"entry{{#if this.isFlip}} flip{{/if}}{{#unless this.src}} no-media{{/unless}}\" data-entry>\n    {{#if this.src}}\n    <div class=\"media\">\n      <div class=\"os-window\">\n        <div class=\"os-titlebar\"><span class=\"name\">{{this.windowLabel}}</span><div class=\"os-btns\"><i></i><i></i><i></i></div></div>\n        <div class=\"stage\">\n          <img class=\"thumb\" src=\"{{{this.src}}}\" alt=\"{{this.imageAlt}}\">\n          <div class=\"scan\"></div><div class=\"tint\"></div><div class=\"vignette\"></div>\n        </div>\n      </div>\n    </div>\n    {{/if}}\n    <div class=\"copy\">\n      <span class=\"index\">{{this.indexLabel}}</span>\n      <h2>{{this.projectName}}</h2>\n      <div class=\"tag-row\">\n        <span class=\"tag blue\">{{this.category}}</span>\n        {{#if this.client}}<span class=\"tag\">Client — {{this.client}}</span>{{/if}}\n      </div>\n      <p class=\"blurb\">{{this.blurb}}</p>\n      <div class=\"stat-line\">{{this.statLine}}</div>\n    </div>\n  </article>\n  {{/if}}\n  {{/each}}\n\n  </div>\n</section>\n\n{{#if (eq galleryPlacement \"end-of-article\")}}\n{{{galleryHtml}}}\n{{/if}}\n\n{{#if cta}}\n<section class=\"cta\">\n  <div class=\"wrap\">\n    <h2>{{cta.heading}}</h2>\n    <p>{{cta.body}}</p>\n    <div class=\"cta-btns\">\n      <a class=\"btn btn-primary\" href=\"#\">Get a quote<span class=\"arrow\">→</span></a>\n      <a class=\"btn btn-ghost\" href=\"#\">See all work<span class=\"arrow\">→</span></a>\n    </div>\n  </div>\n</section>\n{{/if}}\n\n<script>\n  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {\n    var entries = document.querySelectorAll('[data-entry]');\n    var io = new IntersectionObserver(function(items){\n      items.forEach(function(item){\n        item.target.classList.toggle('is-playing', item.isIntersecting);\n      });\n    }, { threshold: 0.4 });\n    entries.forEach(function(el){ io.observe(el); });\n  }\n</script>\n";
const template01Meta_exampleJson = "{\n  \"title\": \"12 PROJECTS THAT SHOW WHAT EDT ACTUALLY BUILDS\",\n  \"dek\": \"No pitch-deck language, just the work — twelve activations, installations and realtime characters we've shipped across Malaysia and the region, with the numbers each one actually posted.\",\n  \"category\": \"Case Studies\",\n  \"readTimeMinutes\": 7,\n  \"intro\": \"Every one of these started as a brief that sounded slightly too ambitious — a hologram that had to hold a real conversation, a projection that had to win against a live jury, an AI persona that had to talk back on a golf course. We build the technical layer other studios say is too complex, then we ship it.\",\n  \"entries\": [\n    {\n      \"windowLabel\": \"METAHRISE.EXE\",\n      \"projectName\": \"MetaHRise\",\n      \"category\": \"VR Training\",\n      \"client\": \"MCMC\",\n      \"blurb\": \"MCMC's induction used to be a slide deck and a printed handbook — forgettable by the second slide. We rebuilt it as a VR game new hires actually finish, learning the organisation by moving through it instead of sitting through it. It's the reason MetaHRise now holds a Malaysia Book of Records entry, not the other way around.\",\n      \"statLine\": \"93% satisfaction · Malaysia Book of Records 2024\",\n      \"imageId\": \"img-1\",\n      \"imageAlt\": \"MetaHRise VR training scene\"\n    },\n    {\n      \"windowLabel\": \"TIGER.EXE\",\n      \"projectName\": \"Say Hello, Tiger\",\n      \"category\": \"Realtime AI Persona\",\n      \"client\": \"Maybank Championship\",\n      \"blurb\": \"Mascots are usually a photo op — wave, pose, move on. The brief asked for one that could actually talk, so we gave Tiger a realtime voice and a face that performs in sync with it. What's in the recap isn't a demo-reel moment; it's an unscripted exchange, captured live on the course.\",\n      \"statLine\": \"Live voice + facial performance, on-ground\",\n      \"imageId\": null,\n      \"imageAlt\": null\n    },\n    {\n      \"windowLabel\": \"CHERITAR.EXE\",\n      \"projectName\": \"CheritAR\",\n      \"category\": \"AR Heritage\",\n      \"client\": \"Think City\",\n      \"blurb\": \"Think City wanted heritage buildings to speak for themselves without another plaque nobody reads. We layered the stories into AR instead — point a phone at a building and the history behind it surfaces on the spot. It's since travelled further than the brief asked for: the same trail has been picked up in twelve countries.\",\n      \"statLine\": \"12 countries reached · 1,442 AR impressions\",\n      \"imageId\": \"img-2\",\n      \"imageAlt\": \"CheritAR heritage trail experience\"\n    },\n    {\n      \"windowLabel\": \"ARFESTKL.EXE\",\n      \"projectName\": \"ARFestKL\",\n      \"category\": \"AR Event\",\n      \"client\": \"ARFestKL\",\n      \"blurb\": \"A festival footprint only means something if people actually walk it. ARFestKL needed Downtown KL turned into a trail dense enough to survive a full weekend of foot traffic, so we built a QR-to-AR funnel engineered to take the volume without breaking. It held — over fifty thousand impressions and twelve thousand scans in two days.\",\n      \"statLine\": \"52,417 AR impressions · 12,040 QR scans\",\n      \"imageId\": \"img-3\",\n      \"imageAlt\": \"ARFestKL festival AR trail\"\n    },\n    {\n      \"windowLabel\": \"IKAT.EXE\",\n      \"projectName\": \"IKAT Malaysia\",\n      \"category\": \"Immersive Exhibition\",\n      \"client\": \"Ministry of Textile\",\n      \"blurb\": \"Ikat weaving is generations of technique that doesn't survive well behind glass. The Ministry of Textile wanted people to feel the craft, not just read a wall label about it, so we staged the history as a full immersive environment instead of a static display. It pulled RM3.2 million in media value and over 5,800 visitors through the doors.\",\n      \"statLine\": \"RM3.2M media value · 5,822 visitors\",\n      \"imageId\": \"img-4\",\n      \"imageAlt\": \"IKAT Malaysia immersive exhibition\"\n    },\n    {\n      \"windowLabel\": \"FOUNDERS.EXE\",\n      \"projectName\": \"AirAsia Founders' Gallery\",\n      \"category\": \"Interactive Installation\",\n      \"client\": \"AirAsia\",\n      \"blurb\": \"A founders' story told as wall text gets skimmed once and forgotten. AirAsia wanted theirs to be a place people actually walk through, so we combined interactive walls, AR overlays and an AI layer into one permanent gallery — the story you touch, not just read.\",\n      \"statLine\": \"Interactive walls + AR + AI, permanent install\",\n      \"imageId\": \"img-5\",\n      \"imageAlt\": \"AirAsia Founders' Gallery interactive wall\"\n    },\n    {\n      \"windowLabel\": \"GREYDAY.EXE\",\n      \"projectName\": \"New Balance Grey Day\",\n      \"category\": \"AR + Immersive Room\",\n      \"client\": \"New Balance\",\n      \"blurb\": \"Sneaker drops live and die on how they photograph. For Grey Day, New Balance needed an experience people would actually queue for and post, so we put a realtime AR try-on inside a fully immersive room built to look good from every angle a phone camera finds.\",\n      \"statLine\": \"Realtime AR try-on experience\",\n      \"imageId\": \"img-6\",\n      \"imageAlt\": \"New Balance Grey Day AR try-on room\"\n    },\n    {\n      \"windowLabel\": \"HOLOGRAM.EXE\",\n      \"projectName\": \"Hologram Stewardess\",\n      \"category\": \"AI Hologram\",\n      \"client\": \"Malaysia Airlines\",\n      \"blurb\": \"A counter needs staffing; a hologram doesn't. Malaysia Airlines needed a first point of contact at MATIC KL that could answer real questions, so we deployed an AI stewardess as a hologram — live, responsive, and on duty for every visitor who walks up.\",\n      \"statLine\": \"Deployed live at MATIC KL\",\n      \"imageId\": \"img-7\",\n      \"imageAlt\": \"Malaysia Airlines hologram stewardess\"\n    },\n    {\n      \"windowLabel\": \"PNB118.EXE\",\n      \"projectName\": \"PNB 118 Stories\",\n      \"category\": \"Interactive Wall\",\n      \"client\": \"PNB\",\n      \"blurb\": \"A tower this size needed a lobby that didn't feel like an afterthought. PNB wanted the building's own story told at its base, so we built the largest interactive wall EDT has shipped for a single structure — the tower's history, made touchable by anyone walking in.\",\n      \"statLine\": \"Largest interactive install built for the tower\",\n      \"imageId\": \"img-8\",\n      \"imageAlt\": \"PNB 118 lobby interactive wall\"\n    },\n    {\n      \"windowLabel\": \"ARVENA.EXE\",\n      \"projectName\": \"AirAsia Supersale\",\n      \"category\": \"Virtual Production\",\n      \"client\": \"AirAsia\",\n      \"blurb\": \"Supersale needed broadcast-grade sets on a campaign timeline, not a construction schedule. We ran the whole shoot through ARVENA, EDT's virtual production platform, building every set in-engine instead of on a soundstage — same polish, none of the build time.\",\n      \"statLine\": \"ARVENA platform, full deployment\",\n      \"imageId\": \"img-9\",\n      \"imageAlt\": \"AirAsia Supersale virtual production set\"\n    },\n    {\n      \"windowLabel\": \"SHAYLA.EXE\",\n      \"projectName\": \"Shayla Sis Shayla\",\n      \"category\": \"AI Virtual Influencer\",\n      \"client\": \"Safi\",\n      \"blurb\": \"Safi didn't want a spokesperson who ages out of a campaign — they wanted a persona that's entirely theirs. We built Shayla from scratch: a face, a voice, and a posting schedule, deployed as a fully virtual influencer for the national campaign.\",\n      \"statLine\": \"National campaign deployment\",\n      \"imageId\": \"img-10\",\n      \"imageAlt\": \"Shayla virtual influencer campaign\"\n    },\n    {\n      \"windowLabel\": \"EARTHQUAKE.EXE\",\n      \"projectName\": \"VR Earthquake Simulation\",\n      \"category\": \"VR Training\",\n      \"client\": \"Tokyo Fire Department\",\n      \"blurb\": \"You can't schedule an earthquake to train for it. Tokyo Fire Department needed responders to feel the disorientation before the real event does, so we built a VR simulation that puts them through the shake — training that rehearses a moment training usually can't reach.\",\n      \"statLine\": \"Deployed for disaster-preparedness training, Japan\",\n      \"imageId\": \"img-11\",\n      \"imageAlt\": \"Tokyo Fire Department VR earthquake simulation\"\n    }\n  ],\n  \"cta\": {\n    \"heading\": \"Got a brief that sounds too ambitious?\",\n    \"body\": \"That's usually the one we want. Tell us what you're trying to build and we'll tell you exactly how EDT would ship it.\"\n  },\n  \"galleryPlacement\": null\n}\n";

const template02Meta_hbs = "<title>Long-Form Article Template</title>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Dela+Gothic+One&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');\n\n  :root{\n    --blue:#2D2DFF;\n    --blue-hover:#0000CC;\n    --black:#0A0A0A;\n    --surface:#111111;\n    --grey:#8C8C8C;\n    --white:#FFFFFF;\n    --border:#FFFFFF;\n    --hairline:rgba(255,255,255,0.14);\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;}\n  body{\n    background:var(--black);\n    color:var(--white);\n    font-family:'Space Grotesk',sans-serif;\n    line-height:1.65;\n    -webkit-font-smoothing:antialiased;\n  }\n  ::selection{background:var(--blue);color:var(--white);}\n  h1,h2,h3{margin:0;text-wrap:balance;}\n  p{margin:0;}\n  a{color:inherit;text-decoration:none;}\n  img,svg{display:block;max-width:100%;}\n  .wrap{max-width:1180px;margin:0 auto;padding-inline:24px;}\n  @media(min-width:900px){.wrap{padding-inline:80px;}}\n  .col{max-width:680px;margin:0 auto;}\n  @media(min-width:1440px){.col{max-width:840px;}}\n\n  .grid-tex{\n    position:absolute;inset:0;\n    background-image:\n      linear-gradient(to right, rgba(255,255,255,0.05) 1px, transparent 1px),\n      linear-gradient(to bottom, rgba(255,255,255,0.05) 1px, transparent 1px);\n    background-size:32px 32px;\n    pointer-events:none;\n  }\n\n  /* ================= READING PROGRESS ================= */\n  .progress-track{position:fixed;top:0;left:0;right:0;height:3px;background:var(--surface);z-index:40;}\n  .progress-bar{height:100%;width:0%;background:var(--blue);transition:width 80ms linear;}\n\n  /* Header/footer/template-tag are intentionally not part of this output —\n     the article is meant to be embedded into the real EDT site/CMS, which\n     supplies its own. .btn/.btn-primary/.btn-ghost/.arrow are kept: the\n     dynamic CTA section at the bottom still uses them. */\n  .btn{\n    display:inline-flex;align-items:center;gap:9px;\n    font-family:'Space Grotesk',sans-serif;font-weight:600;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;\n    padding:13px 22px;border:1px solid var(--blue);\n    transition:background 120ms ease,color 120ms ease,transform 120ms ease;\n  }\n  .btn-primary{background:var(--blue);color:var(--white);}\n  .btn-primary:hover{background:var(--blue-hover);transform:scale(1.02);}\n  .btn-ghost{background:transparent;border-color:var(--white);}\n  .btn-ghost:hover{background:var(--white);color:var(--black);}\n  .arrow{transition:transform 120ms ease;display:inline-block;}\n  .btn:hover .arrow{transform:translateX(3px);}\n\n  /* ================= CRUMB ================= */\n  .crumb-bar{border-bottom:1px solid var(--hairline);}\n  .crumb-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:var(--grey);}\n  .crumb-row .sep{color:var(--blue);margin:0 8px;}\n\n  /* ================= ARTICLE HERO ================= */\n  .article-hero{position:relative;overflow:hidden;padding:56px 0 40px;}\n  .eyebrow{\n    display:inline-flex;align-items:center;gap:8px;\n    font-size:12px;font-weight:600;letter-spacing:0.14em;text-transform:uppercase;color:var(--blue);margin-bottom:20px;\n  }\n  .eyebrow::before{content:\"\";width:8px;height:8px;background:var(--blue);}\n  h1.title{\n    font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;letter-spacing:-0.02em;\n    font-size:clamp(36px,7vw,76px);line-height:1.0;max-width:16ch;\n  }\n  .dek{margin-top:24px;max-width:56ch;font-size:clamp(17px,1.9vw,20px);color:#cfcfcf;font-weight:300;}\n  .byline-row{\n    margin-top:36px;display:flex;flex-wrap:wrap;gap:0;border-top:1px solid var(--hairline);\n  }\n  .byline-item{flex:1 1 140px;padding:16px 20px;border-right:1px solid var(--hairline);}\n  .byline-item:first-child{padding-left:0;}\n  .byline-item:last-child{border-right:none;}\n  .byline-item .k{font-size:10px;letter-spacing:0.1em;text-transform:uppercase;color:var(--grey);margin-bottom:5px;}\n  .byline-item .v{font-size:13px;font-weight:500;}\n\n  /* ================= FEATURE IMAGE ================= */\n  .feature-media{padding:8px 0 64px;}\n  /* Moved into the text column (edit mode can do this), the section's own\n     .wrap would inset the photo a second time — same fix as the galleries. */\n  .col .feature-media{padding:8px 0 40px;}\n  .col .feature-media .wrap{max-width:none;padding-inline:0;}\n  .os-window{border:1px solid var(--border);background:var(--surface);}\n  .os-titlebar{\n    display:flex;align-items:center;justify-content:space-between;background:var(--blue);\n    padding:11px 16px;border-bottom:1px solid var(--border);\n  }\n  .os-titlebar .name{font-size:11px;font-weight:600;letter-spacing:0.05em;}\n  .os-btns{display:flex;gap:5px;}\n  .os-btns i{width:10px;height:10px;border:1px solid var(--white);display:block;}\n  .feature-stage{position:relative;aspect-ratio:16/9;overflow:hidden;}\n  .feature-stage img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;\n    filter:grayscale(.25) contrast(1.12) brightness(.85) saturate(.9);}\n  .feature-stage .tint{position:absolute;inset:0;background:var(--blue);opacity:.2;mix-blend-mode:multiply;}\n  .feature-stage .grid-tex{opacity:.35;}\n  .feature-caption{padding:14px 4px 0;font-size:12px;color:var(--grey);}\n\n  /* ================= ARTICLE BODY ================= */\n  .article-body{padding:0 0 32px;}\n  .lede{font-size:19px;font-weight:400;color:#e8e8e8;margin-bottom:36px;line-height:1.7;}\n  .section-label{\n    display:block;font-size:11px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;\n    color:var(--blue);margin:0 0 18px;\n  }\n\n  /* ---- numbered scroll steps ---- */\n  .steps{margin-top:8px;}\n  .step{\n    position:relative;display:grid;grid-template-columns:1fr;gap:20px;\n    padding:56px 0;border-top:1px solid var(--hairline);\n  }\n  .step:first-child{border-top:none;padding-top:0;}\n  @media(min-width:760px){\n    .step{grid-template-columns:140px 1fr;gap:40px;}\n  }\n  .step-num-col{line-height:1;}\n  @media(min-width:760px){\n    .step-num-col{position:sticky;top:24px;align-self:start;}\n  }\n  .step-num{\n    font-family:'Dela Gothic One',sans-serif;\n    font-size:clamp(48px,6.5vw,88px);line-height:1;\n    color:var(--white);\n  }\n  .body-copy p{font-size:17px;color:#d6d6d6;font-weight:300;line-height:1.8;margin-bottom:22px;}\n  .body-copy p:last-child{margin-bottom:0;}\n  .drop p:first-of-type::first-letter{\n    font-family:'Dela Gothic One',sans-serif;color:var(--blue);\n    font-size:4.4em;line-height:.72;float:left;padding:5px 10px 0 0;\n  }\n\n  [data-reveal]{opacity:0;transform:translateY(22px);transition:opacity .7s ease, transform .7s ease;}\n  [data-reveal].revealed{opacity:1;transform:translateY(0);}\n  @media (prefers-reduced-motion: reduce){[data-reveal]{opacity:1;transform:none;transition:none;}}\n\n  .pull-quote{\n    margin:56px 0;padding-left:28px;border-left:3px solid var(--blue);\n  }\n  .pull-quote p{\n    font-family:'Space Grotesk',sans-serif;font-weight:500;font-size:clamp(22px,3vw,30px);\n    color:var(--white);line-height:1.4;text-wrap:balance;\n  }\n  .pull-quote .src{margin-top:14px;font-size:13px;color:var(--grey);}\n\n  .stat-card{margin:56px 0;}\n  .stat-card .os-titlebar{background:var(--blue);}\n  .stat-grid{display:grid;grid-template-columns:1fr;gap:1px;background:var(--hairline);}\n  @media(min-width:560px){.stat-grid{grid-template-columns:1fr 1fr;}}\n  .stat-cell{background:var(--surface);padding:28px 24px;}\n  .stat-num{font-family:'Dela Gothic One',sans-serif;font-size:clamp(32px,5vw,44px);color:var(--white);}\n  .stat-label{margin-top:8px;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;color:var(--grey);}\n\n  .inline-tags{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 40px;}\n  .tag{border:1px solid var(--border);font-size:10px;letter-spacing:0.08em;text-transform:uppercase;padding:4px 9px;color:var(--grey);}\n  .tag.blue{border-color:var(--blue);color:var(--blue);}\n\n  .closing{padding:8px 0 24px;}\n  .closing p{font-size:17px;color:#d6d6d6;font-weight:300;line-height:1.8;margin-bottom:22px;}\n\n  /* ================= CTA ================= */\n  .cta{padding:88px 0;border-top:1px solid var(--hairline);margin-top:32px;}\n  .cta h2{font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;font-size:clamp(28px,5vw,48px);letter-spacing:-0.02em;max-width:16ch;margin-bottom:18px;}\n  .cta p{color:var(--grey);font-size:16px;max-width:52ch;margin-bottom:32px;font-weight:300;}\n  .cta-btns{display:flex;flex-wrap:wrap;gap:16px;}\n</style>\n\n<div class=\"progress-track\"><div class=\"progress-bar\" id=\"progressBar\"></div></div>\n\n<div class=\"crumb-bar\">\n  <div class=\"wrap crumb-row\">\n    <div><a href=\"#\">Blog</a><span class=\"sep\">/</span><a href=\"#\">Long Read</a></div>\n  </div>\n</div>\n\n<section class=\"article-hero\">\n  <div class=\"grid-tex\" style=\"opacity:.5\"></div>\n  <div class=\"wrap\" style=\"position:relative;\">\n    <div class=\"eyebrow\">EDT Blog — Long read</div>\n    <h1 class=\"title\">{{title}}</h1>\n    <p class=\"dek\">{{dek}}</p>\n    <div class=\"byline-row\">\n      {{#if client}}\n      <div class=\"byline-item\"><div class=\"k\">Client</div><div class=\"v\">{{client}}</div></div>\n      {{/if}}\n      <div class=\"byline-item\"><div class=\"k\">Category</div><div class=\"v\">{{category}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Read time</div><div class=\"v\">{{readTimeLabel}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Format</div><div class=\"v\">Long read</div></div>\n    </div>\n  </div>\n</section>\n\n{{#if featureImage}}\n{{#if featureImage.src}}\n<section class=\"feature-media\">\n  <div class=\"wrap\">\n    <div class=\"os-window\" data-reveal>\n      <div class=\"os-titlebar\"><span class=\"name\">{{featureImage.windowLabel}}</span><div class=\"os-btns\"><i></i><i></i><i></i></div></div>\n      <div class=\"feature-stage\">\n        <img src=\"{{{featureImage.src}}}\" alt=\"{{featureImage.caption}}\">\n        <div class=\"tint\"></div>\n        <div class=\"grid-tex\"></div>\n      </div>\n    </div>\n    <p class=\"feature-caption\">{{featureImage.caption}}</p>\n  </div>\n</section>\n{{/if}}\n{{/if}}\n\n<section class=\"article-body\">\n  <div class=\"wrap col\">\n    <p class=\"lede\">{{lede}}</p>\n\n    {{#if (eq galleryPlacement \"after-intro\")}}\n    {{{galleryHtml}}}\n    {{/if}}\n\n    <div class=\"steps\">\n      {{#each steps}}\n      {{#if this.videoHtml}}\n      {{{this.videoHtml}}}\n      {{else}}\n      <article class=\"step\" data-step>\n        <div class=\"step-num-col\"><span class=\"step-num\">{{this.stepNumberLabel}}</span></div>\n        <div class=\"step-content\">\n          <span class=\"section-label\">{{this.sectionLabel}}</span>\n          <div class=\"body-copy{{#if this.isFirst}} drop{{/if}}\" data-reveal>\n            {{#each this.paragraphs}}\n            <p>{{this}}</p>\n            {{/each}}\n          </div>\n          {{#if this.highlight}}\n          {{{renderHighlight this.highlight}}}\n          {{/if}}\n        </div>\n      </article>\n      {{/if}}\n      {{/each}}\n    </div>\n\n    {{#if closing}}\n    <div class=\"closing\" data-reveal>\n      <p>{{closing}}</p>\n    </div>\n    {{/if}}\n  </div>\n</section>\n\n{{#if (eq galleryPlacement \"before-cta\")}}\n{{{galleryHtml}}}\n{{/if}}\n\n{{#if cta}}\n<section class=\"cta\">\n  <div class=\"wrap\">\n    <h2>{{cta.heading}}</h2>\n    <p>{{cta.body}}</p>\n    <div class=\"cta-btns\">\n      <a class=\"btn btn-primary\" href=\"#\">Get a quote<span class=\"arrow\">→</span></a>\n      <a class=\"btn btn-ghost\" href=\"#\">Read more case studies<span class=\"arrow\">→</span></a>\n    </div>\n  </div>\n</section>\n{{/if}}\n\n<script>\n  var bar = document.getElementById('progressBar');\n  function updateProgress(){\n    var h = document.documentElement;\n    var scrolled = h.scrollTop;\n    var max = h.scrollHeight - h.clientHeight;\n    bar.style.width = (max > 0 ? (scrolled / max) * 100 : 0) + '%';\n  }\n  document.addEventListener('scroll', updateProgress, { passive: true });\n  updateProgress();\n\n  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {\n    var targets = document.querySelectorAll('[data-reveal]');\n    var io = new IntersectionObserver(function(items){\n      items.forEach(function(item){\n        if (item.isIntersecting) {\n          item.target.classList.add('revealed');\n          io.unobserve(item.target);\n        }\n      });\n    }, { threshold: 0.15, rootMargin: '0px 0px -8% 0px' });\n    targets.forEach(function(el){ io.observe(el); });\n  } else {\n    document.querySelectorAll('[data-reveal]').forEach(function(el){ el.classList.add('revealed'); });\n  }\n</script>\n";
const template02Meta_exampleJson = "{\n  \"title\": \"INSIDE METAHRISE\",\n  \"dek\": \"How a corporate induction became a VR game 145 employees actually wanted to finish — and how that game ended up in the Malaysia Book of Records.\",\n  \"category\": \"Case Studies\",\n  \"readTimeMinutes\": 9,\n  \"client\": \"MCMC\",\n  \"featureImage\": {\n    \"windowLabel\": \"METAHRISE.EXE — FIELD_CAPTURE.JPG\",\n    \"caption\": \"MetaHRise on-site at MCMC — new hires moving through the induction as a playable VR environment.\",\n    \"imageId\": \"img-1\"\n  },\n  \"lede\": \"Most inductions are a room, a slide deck, and a printed handbook nobody re-reads after week one. MCMC wanted something that would actually stick — so we didn't design a better slideshow. We built a game.\",\n  \"steps\": [\n    {\n      \"sectionLabel\": \"The brief\",\n      \"paragraphs\": [\n        \"MCMC's induction was doing what most inductions do: covering the material and losing the room by slide four. New hires walked away with a folder and a vague sense of the org chart, not a feel for the organisation they'd just joined. The ask wasn't \\\"make the deck nicer.\\\" It was harder to say out loud and harder to brief: make people want to sit through this.\",\n        \"That's a design problem before it's a technology problem. You can't VR your way out of boring content — you have to change what the person is actually doing while they learn it. Sitting and listening was the thing that had to go.\"\n      ],\n      \"highlight\": {\n        \"type\": \"pullQuote\",\n        \"quote\": \"You can't VR your way out of boring content. You have to change what the person is doing while they learn it.\",\n        \"attribution\": \"— EDT, on the MetaHRise brief\"\n      }\n    },\n    {\n      \"sectionLabel\": \"Why a game, specifically\",\n      \"paragraphs\": [\n        \"Games teach through consequence, not through delivery. Walk the wrong way in a game and you find out immediately — nobody has to tell you. We built MetaHRise on that principle: new hires move through a VR environment structured around MCMC itself, and the organisation's structure, values and history surface as things you discover by playing, not slides you're told to remember.\",\n        \"The headset was the easy part. The harder design problem was pacing — an induction has to hold someone's attention for long enough to cover real material, without ever feeling like a chore wearing a headset. Every beat in MetaHRise earns the next one; nothing plays just to look impressive in a demo reel.\"\n      ],\n      \"highlight\": null\n    },\n    {\n      \"sectionLabel\": \"What we built\",\n      \"paragraphs\": [\n        \"MetaHRise plays as a sequence of environments rather than a single space — each one built around a specific part of the induction, so the content changes the room instead of a narrator changing the topic. Progress is visible and immediate: new hires can see how far they are through the experience the same way they'd see progress in any game, which turned out to matter more than we expected. People finish things they can see the end of.\"\n      ],\n      \"highlight\": {\n        \"type\": \"statCard\",\n        \"windowLabel\": \"RESULTS.EXE\",\n        \"cells\": [\n          { \"number\": \"93%\", \"label\": \"New-hire satisfaction, post-induction survey\" },\n          { \"number\": \"2024\", \"label\": \"Malaysia Book of Records entry\" }\n        ]\n      }\n    },\n    {\n      \"sectionLabel\": \"The record\",\n      \"paragraphs\": [\n        \"The Malaysia Book of Records entry wasn't the brief — it was a consequence of taking the brief seriously. Once MetaHRise existed as a genuinely playable induction, rather than a VR-flavoured slideshow, it qualified as something worth recognising on its own terms. We'd rather ship the record as a side effect than chase it as the headline.\"\n      ],\n      \"highlight\": {\n        \"type\": \"pullQuote\",\n        \"quote\": \"We build the technical layer other studios say is too complex, then we ship it. The record was proof, not the point.\",\n        \"attribution\": \"— EDT, on shipping MetaHRise\"\n      }\n    },\n    {\n      \"sectionLabel\": \"What we'd do differently\",\n      \"paragraphs\": [\n        \"Every project teaches you where you over-built. With MetaHRise, the lesson was about scope discipline inside VR specifically — it's easy to keep adding environments because the medium makes everything feel like it deserves one. The strongest sections were the ones we cut hardest, not the ones we added the most detail to. That's the note we carry into every VR training build since.\"\n      ],\n      \"highlight\": {\n        \"type\": \"tagList\",\n        \"tags\": [\"VR Training\", \"Corporate Onboarding\", \"Malaysia Book of Records\"]\n      }\n    }\n  ],\n  \"closing\": \"MetaHRise is still running inductions at MCMC. The record is framed somewhere in an office we don't visit often enough — the 93% satisfaction number is the one we actually check.\",\n  \"cta\": {\n    \"heading\": \"Got an induction nobody finishes?\",\n    \"body\": \"Tell us what the content actually is and we'll tell you what it should feel like to go through — VR, AR, or otherwise.\"\n  },\n  \"galleryPlacement\": null\n}\n";

const template04Meta_hbs = "<title>Basic Scroll Article Template</title>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Dela+Gothic+One&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');\n\n  :root{\n    --blue:#2D2DFF;\n    --blue-hover:#0000CC;\n    --black:#0A0A0A;\n    --surface:#111111;\n    --grey:#8C8C8C;\n    --white:#FFFFFF;\n    --border:#FFFFFF;\n    --hairline:rgba(255,255,255,0.14);\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;}\n  body{\n    background:var(--black);\n    color:var(--white);\n    font-family:'Space Grotesk',sans-serif;\n    line-height:1.65;\n    -webkit-font-smoothing:antialiased;\n  }\n  ::selection{background:var(--blue);color:var(--white);}\n  h1,h2,h3{margin:0;text-wrap:balance;}\n  p{margin:0;}\n  a{color:inherit;text-decoration:none;}\n  img,svg{display:block;max-width:100%;}\n  .wrap{max-width:1180px;margin:0 auto;padding-inline:24px;}\n  @media(min-width:900px){.wrap{padding-inline:80px;}}\n  @media(min-width:1440px){.wrap{padding-inline:96px;}}\n  .col{max-width:680px;margin:0 auto;}\n  @media(min-width:1440px){.col{max-width:840px;}}\n\n  .grid-tex{\n    position:absolute;inset:0;\n    background-image:\n      linear-gradient(to right, rgba(255,255,255,0.05) 1px, transparent 1px),\n      linear-gradient(to bottom, rgba(255,255,255,0.05) 1px, transparent 1px);\n    background-size:32px 32px;\n    pointer-events:none;\n  }\n\n  /* ================= READING PROGRESS ================= */\n  .progress-track{position:fixed;top:0;left:0;right:0;height:3px;background:var(--surface);z-index:40;}\n  .progress-bar{height:100%;width:0%;background:var(--blue);transition:width 80ms linear;}\n\n  /* Header/footer/template-tag are intentionally not part of this output —\n     the article is meant to be embedded into the real EDT site/CMS, which\n     supplies its own. .btn/.btn-primary/.btn-ghost/.arrow are kept: the\n     dynamic CTA section at the bottom still uses them. */\n  .btn{\n    display:inline-flex;align-items:center;gap:9px;\n    font-family:'Space Grotesk',sans-serif;font-weight:600;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;\n    padding:13px 22px;border:1px solid var(--blue);\n    transition:background 120ms ease,color 120ms ease,transform 120ms ease;\n  }\n  .btn-primary{background:var(--blue);color:var(--white);}\n  .btn-primary:hover{background:var(--blue-hover);transform:scale(1.02);}\n  .btn-ghost{background:transparent;border-color:var(--white);}\n  .btn-ghost:hover{background:var(--white);color:var(--black);}\n  .arrow{transition:transform 120ms ease;display:inline-block;}\n  .btn:hover .arrow{transform:translateX(3px);}\n\n  /* ================= CRUMB ================= */\n  .crumb-bar{border-bottom:1px solid var(--hairline);}\n  .crumb-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:var(--grey);}\n  .crumb-row .sep{color:var(--blue);margin:0 8px;}\n\n  /* ================= ARTICLE HERO ================= */\n  .article-hero{position:relative;overflow:hidden;padding:56px 0 40px;}\n  .eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:600;letter-spacing:0.14em;text-transform:uppercase;color:var(--blue);margin-bottom:20px;}\n  .eyebrow::before{content:\"\";width:8px;height:8px;background:var(--blue);}\n  h1.title{\n    font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;letter-spacing:-0.02em;\n    font-size:clamp(36px,7vw,76px);line-height:1.0;max-width:16ch;\n  }\n  .dek{margin-top:24px;max-width:56ch;font-size:clamp(17px,1.9vw,20px);color:#cfcfcf;font-weight:300;}\n  .byline-row{margin-top:36px;display:flex;flex-wrap:wrap;border-top:1px solid var(--hairline);}\n  .byline-item{flex:1 1 140px;padding:16px 20px;border-right:1px solid var(--hairline);}\n  .byline-item:first-child{padding-left:0;}\n  .byline-item:last-child{border-right:none;}\n  .byline-item .k{font-size:10px;letter-spacing:0.1em;text-transform:uppercase;color:var(--grey);margin-bottom:5px;}\n  .byline-item .v{font-size:13px;font-weight:500;}\n\n  /* ================= FEATURE IMAGE ================= */\n  .feature-media{padding:8px 0 64px;}\n  /* Moved into the text column (edit mode can do this), the section's own\n     .wrap would inset the photo a second time — same fix as the galleries. */\n  .col .feature-media{padding:8px 0 40px;}\n  .col .feature-media .wrap{max-width:none;padding-inline:0;}\n  .os-window{border:1px solid var(--border);background:var(--surface);}\n  .os-titlebar{display:flex;align-items:center;justify-content:space-between;background:var(--blue);padding:11px 16px;border-bottom:1px solid var(--border);}\n  .os-titlebar .name{font-size:11px;font-weight:600;letter-spacing:0.05em;}\n  .os-btns{display:flex;gap:5px;}\n  .os-btns i{width:10px;height:10px;border:1px solid var(--white);display:block;}\n  .feature-stage{position:relative;aspect-ratio:16/9;overflow:hidden;}\n  .feature-stage img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:grayscale(.25) contrast(1.12) brightness(.85) saturate(.9);}\n  .feature-stage .tint{position:absolute;inset:0;background:var(--blue);opacity:.2;mix-blend-mode:multiply;}\n  .feature-stage .grid-tex{opacity:.35;}\n  .feature-caption{padding:14px 4px 0;font-size:12px;color:var(--grey);}\n\n  /* ================= ARTICLE BODY (flat, no numbered steps) ================= */\n  .article-body{padding:0 0 32px;}\n  .lede{font-size:19px;font-weight:400;color:#e8e8e8;margin-bottom:36px;line-height:1.7;}\n  .section-label{\n    display:block;font-size:11px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;\n    color:var(--blue);margin:52px 0 18px;\n  }\n  .section-label:first-child{margin-top:0;}\n  .body-copy p{font-size:17px;color:#d6d6d6;font-weight:300;line-height:1.8;margin-bottom:22px;}\n  .body-copy p:last-child{margin-bottom:0;}\n  .drop p:first-of-type::first-letter{\n    font-family:'Dela Gothic One',sans-serif;color:var(--blue);\n    font-size:4.4em;line-height:.72;float:left;padding:5px 10px 0 0;\n  }\n\n  [data-reveal]{opacity:0;transform:translateY(22px);transition:opacity .7s ease, transform .7s ease;}\n  [data-reveal].revealed{opacity:1;transform:translateY(0);}\n  @media (prefers-reduced-motion: reduce){[data-reveal]{opacity:1;transform:none;transition:none;}}\n\n  .pull-quote{margin:56px 0;padding-left:28px;border-left:3px solid var(--blue);}\n  .pull-quote p{\n    font-family:'Space Grotesk',sans-serif;font-weight:500;font-size:clamp(22px,3vw,30px);\n    color:var(--white);line-height:1.4;text-wrap:balance;\n  }\n  .pull-quote .src{margin-top:14px;font-size:13px;color:var(--grey);}\n\n  .stat-card{margin:56px 0;}\n  .stat-card .os-titlebar{background:var(--blue);}\n  .stat-grid{display:grid;grid-template-columns:1fr;gap:1px;background:var(--hairline);}\n  @media(min-width:560px){.stat-grid{grid-template-columns:1fr 1fr;}}\n  .stat-cell{background:var(--surface);padding:28px 24px;}\n  .stat-num{font-family:'Dela Gothic One',sans-serif;font-size:clamp(32px,5vw,44px);color:var(--white);}\n  .stat-label{margin-top:8px;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;color:var(--grey);}\n\n  .inline-tags{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 40px;}\n  .tag{border:1px solid var(--border);font-size:10px;letter-spacing:0.08em;text-transform:uppercase;padding:4px 9px;color:var(--grey);}\n  .tag.blue{border-color:var(--blue);color:var(--blue);}\n\n  .closing{padding:8px 0 24px;}\n  .closing p{font-size:17px;color:#d6d6d6;font-weight:300;line-height:1.8;margin-bottom:22px;}\n\n  /* ================= CTA ================= */\n  .cta{padding:88px 0;border-top:1px solid var(--hairline);margin-top:32px;}\n  .cta h2{font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;font-size:clamp(28px,5vw,48px);letter-spacing:-0.02em;max-width:16ch;margin-bottom:18px;}\n  .cta p{color:var(--grey);font-size:16px;max-width:52ch;margin-bottom:32px;font-weight:300;}\n  .cta-btns{display:flex;flex-wrap:wrap;gap:16px;}\n</style>\n\n<div class=\"progress-track\"><div class=\"progress-bar\" id=\"progressBar\"></div></div>\n\n<div class=\"crumb-bar\">\n  <div class=\"wrap crumb-row\">\n    <div><a href=\"#\">Blog</a><span class=\"sep\">/</span><a href=\"#\">Long Read</a></div>\n  </div>\n</div>\n\n<section class=\"article-hero\">\n  <div class=\"grid-tex\" style=\"opacity:.5\"></div>\n  <div class=\"wrap\" style=\"position:relative;\">\n    <div class=\"eyebrow\">EDT Blog — Long read</div>\n    <h1 class=\"title\">{{title}}</h1>\n    <p class=\"dek\">{{dek}}</p>\n    <div class=\"byline-row\">\n      {{#if client}}\n      <div class=\"byline-item\"><div class=\"k\">Client</div><div class=\"v\">{{client}}</div></div>\n      {{/if}}\n      <div class=\"byline-item\"><div class=\"k\">Category</div><div class=\"v\">{{category}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Read time</div><div class=\"v\">{{readTimeLabel}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Format</div><div class=\"v\">Long read</div></div>\n    </div>\n  </div>\n</section>\n\n{{#if featureImage}}\n{{#if featureImage.src}}\n<section class=\"feature-media\">\n  <div class=\"wrap\">\n    <div class=\"os-window\" data-reveal>\n      <div class=\"os-titlebar\"><span class=\"name\">{{featureImage.windowLabel}}</span><div class=\"os-btns\"><i></i><i></i><i></i></div></div>\n      <div class=\"feature-stage\">\n        <img src=\"{{{featureImage.src}}}\" alt=\"{{featureImage.caption}}\">\n        <div class=\"tint\"></div>\n        <div class=\"grid-tex\"></div>\n      </div>\n    </div>\n    <p class=\"feature-caption\">{{featureImage.caption}}</p>\n  </div>\n</section>\n{{/if}}\n{{/if}}\n\n<section class=\"article-body\">\n  <div class=\"wrap col\">\n    <p class=\"lede\">{{lede}}</p>\n\n    {{#if (eq galleryPlacement \"after-intro\")}}\n    {{{galleryHtml}}}\n    {{/if}}\n\n    {{#each bodyItems}}\n    {{#if this.videoHtml}}\n    {{{this.videoHtml}}}\n    {{else if (eq this.type \"section\")}}\n    <span class=\"section-label\">{{this.sectionLabel}}</span>\n    <div class=\"body-copy{{#if this.isFirstSection}} drop{{/if}}\" data-reveal>\n      {{#each this.paragraphs}}\n      <p>{{this}}</p>\n      {{/each}}\n    </div>\n    {{else}}\n    {{{renderHighlight this.highlight}}}\n    {{/if}}\n    {{/each}}\n\n    {{#if closing}}\n    <div class=\"closing\" data-reveal>\n      <p>{{closing}}</p>\n    </div>\n    {{/if}}\n  </div>\n</section>\n\n{{#if (eq galleryPlacement \"before-cta\")}}\n{{{galleryHtml}}}\n{{/if}}\n\n{{#if cta}}\n<section class=\"cta\">\n  <div class=\"wrap\">\n    <h2>{{cta.heading}}</h2>\n    <p>{{cta.body}}</p>\n    <div class=\"cta-btns\">\n      <a class=\"btn btn-primary\" href=\"#\">Get a quote<span class=\"arrow\">→</span></a>\n      <a class=\"btn btn-ghost\" href=\"#\">Read more case studies<span class=\"arrow\">→</span></a>\n    </div>\n  </div>\n</section>\n{{/if}}\n\n<script>\n  var bar = document.getElementById('progressBar');\n  function updateProgress(){\n    var h = document.documentElement;\n    var scrolled = h.scrollTop;\n    var max = h.scrollHeight - h.clientHeight;\n    bar.style.width = (max > 0 ? (scrolled / max) * 100 : 0) + '%';\n  }\n  document.addEventListener('scroll', updateProgress, { passive: true });\n  updateProgress();\n\n  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {\n    var targets = document.querySelectorAll('[data-reveal]');\n    var io = new IntersectionObserver(function(items){\n      items.forEach(function(item){\n        if (item.isIntersecting) {\n          item.target.classList.add('revealed');\n          io.unobserve(item.target);\n        }\n      });\n    }, { threshold: 0.15, rootMargin: '0px 0px -8% 0px' });\n    targets.forEach(function(el){ io.observe(el); });\n  } else {\n    document.querySelectorAll('[data-reveal]').forEach(function(el){ el.classList.add('revealed'); });\n  }\n</script>\n";
const template04Meta_exampleJson = "{\n  \"title\": \"INSIDE METAHRISE\",\n  \"dek\": \"How a corporate induction became a VR game 145 employees actually wanted to finish — and how that game ended up in the Malaysia Book of Records.\",\n  \"category\": \"Case Studies\",\n  \"readTimeMinutes\": 9,\n  \"client\": \"MCMC\",\n  \"featureImage\": {\n    \"windowLabel\": \"METAHRISE.EXE — FIELD_CAPTURE.JPG\",\n    \"caption\": \"MetaHRise on-site at MCMC — new hires moving through the induction as a playable VR environment.\",\n    \"imageId\": \"img-1\"\n  },\n  \"lede\": \"Most inductions are a room, a slide deck, and a printed handbook nobody re-reads after week one. MCMC wanted something that would actually stick — so we didn't design a better slideshow. We built a game.\",\n  \"bodyItems\": [\n    {\n      \"type\": \"section\",\n      \"sectionLabel\": \"The brief\",\n      \"paragraphs\": [\n        \"MCMC's induction was doing what most inductions do: covering the material and losing the room by slide four. New hires walked away with a folder and a vague sense of the org chart, not a feel for the organisation they'd just joined. The ask wasn't \\\"make the deck nicer.\\\" It was harder to say out loud and harder to brief: make people want to sit through this.\",\n        \"That's a design problem before it's a technology problem. You can't VR your way out of boring content — you have to change what the person is actually doing while they learn it. Sitting and listening was the thing that had to go.\"\n      ]\n    },\n    {\n      \"type\": \"highlight\",\n      \"highlight\": {\n        \"type\": \"pullQuote\",\n        \"quote\": \"You can't VR your way out of boring content. You have to change what the person is doing while they learn it.\",\n        \"attribution\": \"— EDT, on the MetaHRise brief\"\n      }\n    },\n    {\n      \"type\": \"section\",\n      \"sectionLabel\": \"Why a game, specifically\",\n      \"paragraphs\": [\n        \"Games teach through consequence, not through delivery. Walk the wrong way in a game and you find out immediately — nobody has to tell you. We built MetaHRise on that principle: new hires move through a VR environment structured around MCMC itself, and the organisation's structure, values and history surface as things you discover by playing, not slides you're told to remember.\",\n        \"The headset was the easy part. The harder design problem was pacing — an induction has to hold someone's attention for long enough to cover real material, without ever feeling like a chore wearing a headset. Every beat in MetaHRise earns the next one; nothing plays just to look impressive in a demo reel.\"\n      ]\n    },\n    {\n      \"type\": \"section\",\n      \"sectionLabel\": \"What we built\",\n      \"paragraphs\": [\n        \"MetaHRise plays as a sequence of environments rather than a single space — each one built around a specific part of the induction, so the content changes the room instead of a narrator changing the topic. Progress is visible and immediate: new hires can see how far they are through the experience the same way they'd see progress in any game, which turned out to matter more than we expected. People finish things they can see the end of.\"\n      ]\n    },\n    {\n      \"type\": \"highlight\",\n      \"highlight\": {\n        \"type\": \"statCard\",\n        \"windowLabel\": \"RESULTS.EXE\",\n        \"cells\": [\n          { \"number\": \"93%\", \"label\": \"New-hire satisfaction, post-induction survey\" },\n          { \"number\": \"2024\", \"label\": \"Malaysia Book of Records entry\" }\n        ]\n      }\n    },\n    {\n      \"type\": \"section\",\n      \"sectionLabel\": \"The record\",\n      \"paragraphs\": [\n        \"The Malaysia Book of Records entry wasn't the brief — it was a consequence of taking the brief seriously. Once MetaHRise existed as a genuinely playable induction, rather than a VR-flavoured slideshow, it qualified as something worth recognising on its own terms. We'd rather ship the record as a side effect than chase it as the headline.\"\n      ]\n    },\n    {\n      \"type\": \"highlight\",\n      \"highlight\": {\n        \"type\": \"pullQuote\",\n        \"quote\": \"We build the technical layer other studios say is too complex, then we ship it. The record was proof, not the point.\",\n        \"attribution\": \"— EDT, on shipping MetaHRise\"\n      }\n    },\n    {\n      \"type\": \"section\",\n      \"sectionLabel\": \"What we'd do differently\",\n      \"paragraphs\": [\n        \"Every project teaches you where you over-built. With MetaHRise, the lesson was about scope discipline inside VR specifically — it's easy to keep adding environments because the medium makes everything feel like it deserves one. The strongest sections were the ones we cut hardest, not the ones we added the most detail to. That's the note we carry into every VR training build since.\"\n      ]\n    },\n    {\n      \"type\": \"highlight\",\n      \"highlight\": {\n        \"type\": \"tagList\",\n        \"tags\": [\"VR Training\", \"Corporate Onboarding\", \"Malaysia Book of Records\"]\n      }\n    }\n  ],\n  \"closing\": \"MetaHRise is still running inductions at MCMC. The record is framed somewhere in an office we don't visit often enough — the 93% satisfaction number is the one we actually check.\",\n  \"cta\": {\n    \"heading\": \"Got an induction nobody finishes?\",\n    \"body\": \"Tell us what the content actually is and we'll tell you what it should feel like to go through — VR, AR, or otherwise.\"\n  },\n  \"galleryPlacement\": null\n}\n";

const galleryAccordionMeta_hbs = "<style>\n  .gallery-wrap{max-width:1180px;margin:0 auto;padding:40px 24px;}\n  @media(min-width:900px){.gallery-wrap{padding:56px 80px;}}\n  /* Dropped INSIDE an article's text column (.col in the scroll templates,\n     .article-main in the TOC one, .roundup in the project roundup) the column\n     already supplies the gutter, so\n     the wrapper's own max-width and side padding would inset the gallery a\n     second time and leave it narrower than the copy beside it. Clear them\n     there and let the gallery span the column edge to edge. At page level\n     the wrapper keeps them, so it still lines up with the article's .wrap. */\n  .col .gallery-wrap,\n  .roundup .gallery-wrap,\n  .article-main .gallery-wrap{max-width:none;padding-left:0;padding-right:0;}\n\n  /* ============ ACCORDION GALLERY — drop this block into any article ============ */\n  .accordion{\n    display:flex;gap:6px;height:min(72vh,620px);border:1px solid var(--hairline);padding:6px;background:var(--surface);\n  }\n  .panel{position:relative;flex:1;overflow:hidden;cursor:pointer;transition:flex 0.6s cubic-bezier(.19,1,.22,1);min-width:44px;}\n  .accordion:not(:hover) .panel[data-default=\"true\"]{flex:6;}\n  .accordion .panel:hover{flex:6;}\n  .panel img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:grayscale(.2) contrast(1.1) brightness(.82) saturate(.95);}\n  .panel .tint{position:absolute;inset:0;background:var(--blue);opacity:.18;mix-blend-mode:multiply;}\n  .panel .scrim{position:absolute;inset:0;background:linear-gradient(180deg, rgba(0,0,0,0) 45%, rgba(0,0,0,.85) 100%);}\n  .panel .index{position:absolute;top:14px;left:14px;font-family:'Space Grotesk',sans-serif;font-size:11px;font-weight:700;color:rgba(255,255,255,0.85);letter-spacing:0.06em;}\n  .panel .cap{position:absolute;left:14px;right:14px;bottom:14px;opacity:0;transition:opacity .3s ease .1s;white-space:nowrap;}\n  .accordion:not(:hover) .panel[data-default=\"true\"] .cap,\n  .accordion .panel:hover .cap{opacity:1;}\n  .panel .cap .tag{display:inline-block;border:1px solid var(--blue);color:var(--blue);background:rgba(10,10,10,0.6);font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;padding:3px 8px;margin-bottom:8px;}\n  .panel .cap h3{font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:19px;color:var(--white);line-height:1.25;}\n  .panel .cap p{margin-top:4px;font-size:12.5px;color:rgba(255,255,255,0.8);font-weight:300;}\n  .panel-empty{\n    position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:12px;\n    background:repeating-linear-gradient(45deg, var(--black), var(--black) 8px, var(--surface) 8px, var(--surface) 16px);\n    color:var(--grey);font-family:'Space Grotesk',sans-serif;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;\n    writing-mode:vertical-rl;\n  }\n  .accordion:not(:hover) .panel[data-default=\"true\"] .panel-empty,\n  .panel:hover .panel-empty{writing-mode:horizontal-tb;}\n  @media(max-width:760px){\n    .panel-empty{writing-mode:horizontal-tb;}\n  }\n  @media(max-width:760px){\n    .accordion{flex-direction:column;height:auto;}\n    .panel{flex:none !important;height:64px;transition:height .5s ease;}\n    .accordion:not(:hover) .panel[data-default=\"true\"]{height:340px;}\n    .panel:hover, .panel:focus-within{height:340px;}\n    .panel .cap{white-space:normal;}\n  }\n</style>\n\n<div class=\"gallery-wrap\">\n  <div class=\"accordion\">\n    {{#each items}}\n    <div class=\"panel\"{{#if this.isDefault}} data-default=\"true\"{{/if}}>\n      {{#if this.src}}\n      <img src=\"{{{this.src}}}\" alt=\"placeholder\">\n      <div class=\"tint\"></div><div class=\"scrim\"></div>\n      {{else}}\n      <div class=\"panel-empty\">No photo</div>\n      {{/if}}\n      <span class=\"index\">{{pad2 @index}}</span>\n      {{#if this.hasCaption}}\n      <div class=\"cap\">{{#if this.tag}}<span class=\"tag\">{{this.tag}}</span>{{/if}}{{#if this.title}}<h3>{{this.title}}</h3>{{/if}}{{#if this.metric}}<p>{{this.metric}}</p>{{/if}}</div>\n      {{/if}}\n    </div>\n    {{/each}}\n  </div>\n</div>\n";
const galleryAccordionMeta_exampleJson = "{\n  \"items\": [\n    { \"imageId\": \"img-1\", \"tag\": \"AR Event\", \"title\": \"ARFestKL\", \"metric\": \"52,417 AR impressions · 12,040 QR scans\" },\n    { \"imageId\": \"img-2\", \"tag\": \"Immersive Exhibition\", \"title\": \"IKAT Malaysia\", \"metric\": \"RM3.2M media value · 5,822 visitors\" },\n    { \"imageId\": \"img-3\", \"tag\": \"AR Heritage\", \"title\": \"CheritAR\", \"metric\": \"12 countries reached · 1,442 AR impressions\" },\n    { \"imageId\": \"img-4\", \"tag\": \"AR + Immersive Room\", \"title\": \"New Balance Grey Day\", \"metric\": \"Realtime AR try-on experience\" },\n    { \"imageId\": \"img-5\", \"tag\": \"Interactive Wall\", \"title\": \"PNB 118 Stories\", \"metric\": \"Largest interactive install built for the tower\" },\n    { \"imageId\": \"img-6\", \"tag\": \"Interactive Installation\", \"title\": \"AirAsia Founders' Gallery\", \"metric\": \"Interactive walls + AR + AI, permanent install\" }\n  ]\n}\n";

const galleryFlipcardsAlternatingMeta_hbs = "<style>\n  .gallery-wrap{max-width:1180px;margin:0 auto;padding:40px 24px;}\n  @media(min-width:900px){.gallery-wrap{padding:56px 80px;}}\n  /* Dropped INSIDE an article's text column (.col in the scroll templates,\n     .article-main in the TOC one, .roundup in the project roundup) the column\n     already supplies the gutter, so\n     the wrapper's own max-width and side padding would inset the gallery a\n     second time and leave it narrower than the copy beside it. Clear them\n     there and let the gallery span the column edge to edge. At page level\n     the wrapper keeps them, so it still lines up with the article's .wrap. */\n  .col .gallery-wrap,\n  .roundup .gallery-wrap,\n  .article-main .gallery-wrap{max-width:none;padding-left:0;padding-right:0;}\n\n  /* ============ FLIP-CARD GALLERY — drop this block into any article ============ */\n  .flip-grid{display:grid;grid-template-columns:1fr;gap:16px;}\n  @media(min-width:640px){.flip-grid{grid-template-columns:repeat(2,1fr);}}\n  @media(min-width:980px){.flip-grid{grid-template-columns:repeat(3,1fr);}}\n\n  .flip-card{position:relative;aspect-ratio:16/10;perspective:1200px;cursor:pointer;}\n  .flip-inner{position:relative;width:100%;height:100%;transition:transform .6s cubic-bezier(.19,1,.22,1);transform-style:preserve-3d;}\n  .flip-card:hover .flip-inner,\n  .flip-card.flipped .flip-inner{transform:rotateY(180deg);}\n  .flip-face{position:absolute;inset:0;backface-visibility:hidden;-webkit-backface-visibility:hidden;border:1px solid var(--hairline);overflow:hidden;}\n  .flip-front img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:grayscale(.2) contrast(1.1) brightness(.82) saturate(.95);}\n  .flip-front .tint{position:absolute;inset:0;background:var(--blue);opacity:.2;mix-blend-mode:multiply;}\n  .flip-front .scrim{position:absolute;inset:0;background:linear-gradient(180deg, rgba(0,0,0,0) 55%, rgba(0,0,0,.8) 100%);}\n  .flip-front .label{position:absolute;left:14px;bottom:14px;right:14px;font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:15px;color:var(--white);}\n  .flip-front .hint{position:absolute;top:12px;right:12px;width:26px;height:26px;border:1px solid rgba(255,255,255,.5);display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--white);}\n  .flip-back{transform:rotateY(180deg);background:var(--blue);padding:20px;display:flex;flex-direction:column;justify-content:space-between;}\n  .flip-back .tag{font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(255,255,255,0.8);}\n  .flip-back p{font-size:14px;color:var(--white);font-weight:400;line-height:1.55;margin-top:10px;}\n  .flip-back .stack{font-size:11px;color:rgba(255,255,255,0.75);margin-top:auto;padding-top:10px;border-top:1px solid rgba(255,255,255,.25);}\n  .flip-front-empty{\n    position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:16px;\n    background:repeating-linear-gradient(45deg, var(--black), var(--black) 8px, var(--surface) 8px, var(--surface) 16px);\n    color:var(--grey);font-family:'Space Grotesk',sans-serif;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;\n  }\n  @media (prefers-reduced-motion: reduce){.flip-inner{transition:none;}}\n</style>\n\n<div class=\"gallery-wrap\">\n  <div class=\"flip-grid\">\n    {{#each items}}\n    <div class=\"flip-card\" tabindex=\"0\">\n      <div class=\"flip-inner\">\n        <div class=\"flip-face flip-front\">\n          {{#if this.src}}\n          <img src=\"{{{this.src}}}\" alt=\"placeholder\"><div class=\"tint\"></div><div class=\"scrim\"></div>\n          {{else}}\n          <div class=\"flip-front-empty\">No photo provided</div>\n          {{/if}}\n          <span class=\"hint\">↻</span>{{#if this.label}}<div class=\"label\">{{this.label}}</div>{{/if}}\n        </div>\n        <div class=\"flip-face flip-back\">\n          <span class=\"tag\">{{this.indexTag}}</span>\n          {{#if this.body}}<p>{{this.body}}</p>{{/if}}\n          {{#if this.projectLine}}<div class=\"stack\">{{this.projectLine}}</div>{{/if}}\n        </div>\n      </div>\n    </div>\n    {{/each}}\n  </div>\n</div>\n\n<script>\n  document.querySelectorAll('.flip-card').forEach(function(card){\n    card.addEventListener('click', function(){ card.classList.toggle('flipped'); });\n    card.addEventListener('keydown', function(e){\n      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); card.classList.toggle('flipped'); }\n    });\n  });\n</script>\n";
